@Appender(
    _shared_docs["melt"]
    % dict(caller="pd.melt(df, ", versionadded="", other="DataFrame.melt")
)
def melt(
    frame: DataFrame,
    id_vars=None,
    value_vars=None,
    var_name='variable',
    value_name="value",
    col_level=None,
) -> DataFrame:
    if isinstance(frame.columns, ABCMultiIndex):
        cols = [x for c in frame.columns for x in c]
    else:
        cols = list(frame.columns)

    # Validate and prepare id_vars
    if id_vars is not None:
        if not is_list_like(id_vars):
            id_vars = [id_vars]
        # Check presence of each id_var in frame
        missing = Index(np.ravel(id_vars)).difference(cols)
        if not missing.empty:
            raise KeyError(
                "The following 'id_vars' are not present in the DataFrame: {missing}"
                .format(missing=list(missing))
            )
    else:
        id_vars = []

    # Validate and prepare value_vars
    if value_vars is not None:
        if not is_list_like(value_vars):
            value_vars = [value_vars]
        # Check presence of each value_var in frame
        missing = Index(np.ravel(value_vars)).difference(cols)
        if not missing.empty:
            raise KeyError(
                "The following 'value_vars' are not present in the DataFrame: {missing}"
                .format(missing=list(missing))
            )
        frame = frame.loc[:, id_vars + value_vars]
    else:
        frame = frame.copy()

    if col_level is not None:  # Allow for MultiIndex levels
        frame.columns = frame.columns.get_level_values(col_level)

    # Handling var_name logic
    if var_name is None:
        var_name = ['variable'] if not isinstance(frame.columns, ABCMultiIndex) else frame.columns.names

    if isinstance(var_name, str):
        var_name = [var_name]

    N, K = frame.shape
    K -= len(id_vars)

    # Prepare melt data
    mdata = {}
    for col in id_vars:
        id_data = frame.pop(col)
        if is_extension_array_dtype(id_data):
            id_data = concat([id_data] * K, ignore_index=True)
        else:
            id_data = np.tile(id_data.values, K)
        mdata[col] = id_data

    mdata[value_name] = frame.values.ravel("F")
    for i, col in enumerate(var_name):
        mdata[col] = np.asanyarray(frame.columns._get_level_values(i)).repeat(N)

    mcolumns = id_vars + var_name + [value_name]

    return frame._constructor(mdata, columns=mcolumns)
